    detail: {
      url: 'http://www.cema.gov.vn/gioi-thieu/cong-dong-54-dan-toc/nguoi-chut.htm',
      images: [],
      title: 'NGƯỜI CHỨT',
      self_name: 'Chứt.',
      other_names: 'Rục, Arem, Sách.',
      local_groups: 'Mày, Rục, Sách, Arem, Mã Liềng.',
      population:
        '7.513 người (Theo số liệu Điều tra 53 dân tộc thiểu số 01/4/ 2019).',
      language: 'Tiếng nói thuộc nhóm ngôn ngữ Việt - Mường (ngữ hệ Nam Á).',
      history:
        'Quê hương xưa của người Chứt thuộc địa bàn cư trú của người Việt ở hai huyện Bố Trạch và Quảng Trạch, tỉnh Quảng Bình. Vì nạn giặc giã, thuế khoá nặng nề nên họ phải chạy lên nương náu ở vùng núi, một số dần dần chuyển sâu vào vùng phía tây thuộc hai huyện Minh Hoá và Bố Trạch tỉnh Quảng Bình. Theo gia phả của một số dòng họ người Việt trong vùng thì các nhóm Rục, Sách cư trú tại vùng núi này ít nhất đã được trên 500 năm nay.',
      economic_activities:
        'Người Chứt sống bằng nông nghiệp nương rẫy du canh và săn bắn hái lượm. Trừ nhóm Sách sống bằng nông nghiệp còn các nhóm khác hái lượm và săn bắn chiếm vị trí quan trọng, thậm chí là nguồn sống chính trong những năm mất mùa. Các giống cây trồng chính là ngô, sắn, đỗ, lúa.',
      food: 'Lương thực chủ yếu là ngô, sắn. Ngày ăn hai bữa trưa và tối. Những năm mất mùa, họ phải ăn bột báng (bột nhúc) đồ thay cơm quanh năm.',
      clothing:
        'Người Chứt không biết dệt vải, vải mặc mua hoặc trao đổi với người Việt, người Lào trong vùng giáp biên. Mùa hè, nam giới đóng khố, cởi trần. Phụ nữ mặc váy. Mùa đông, họ mặc áo làm bằng vỏ cây. Hiện nay đồng bào ăn mặc giống như người Việt.',
      housing:
        'Họ quen ở trong các túp lều dùng dây buộc, dùng cột ngoãm hay ở trong các hang đá, mái đá. Cho đến trước năm 1954 các nhóm Rục, Arem chủ yếu vẫn sống trong các hang đá, mái đá. Ngày nay, họ sống tập trung ở các bản nhỏ trong các thung lũng. Nhà cửa đã khang trang hơn trước.',
      transportation: 'Phổ biến là gùi có dây đeo vai, vác hoặc người kéo.',
      social_relations:
        'Người Chứt gọi làng là Cà Vên. Mỗi làng thường chỉ có dăm bảy hoặc mười gia đình của một dòng họ cư trú. Ðôi khi các gia đình trong một họ lại cư trú ở nhiều làng khác nhau. Ðứng đầu mỗi làng là Pừ Cà Vên. Ông ta giữ luôn cả vai trò tôn giáo.',
      childbirth:
        'Sắp đến ngày ở cữ, người chồng thường dựng một cái lều nhỏ cho vợ ở ngoài rừng. Thỉnh thoảng anh ta đến thăm nom, tiếp tế lương thực và đồ ăn uống cho vợ. Phụ nữ quen đẻ đứng và tự xoay sở lấy hết thảy mọi việc. Ðẻ xong, người sản phụ tự mình nhóm lửa, đốt nóng một hòn đá cuội để sẵn rồi dội nước lã vào cho bốc hơi nóng để xông khói. Sau 7 ngày, người chồng mới đến đón vợ con vào nhà.',
      marriage:
        'Trai gái đến tuổi trưởng thành, được tự do tìm hiểu yêu đương. Trước khi cưới, nhà trai phải chọn ông mối, đi dạm hỏi vài lần. Lễ cưới được tổ chức bên nhà gái, sau đó mới đón dâu. Lễ vật quan trọng nhất thiết phải có thịt khỉ sấy khô. Người Chứt không có tục ở rể.',
      funeral:
        'Nhà giàu làm quan tài bằng thân cây khoét rỗng; nhà nghèo chỉ bó người chết bằng vỏ cây.',
      worship:
        'Tổ tiên được thờ tại nhà tộc trưởng. Khi tộc trưởng chết, việc thờ cúng chuyển sang người em trai kế. Khi nào các thế hệ trên không còn ai thì việc thờ cúng mới chuyển sang cho người ở thế hệ dưới.',
      arts: 'Người Chứt thích dùng đàn, sáo, hát các giai điệu khác nhau. Họ có nhiều truyện cổ tích, thần thoại, đặc biệt truyện kể về sự khai thiên lập địa và sinh ra con người.',
      entertainment:
        'Trong các dịp lễ tết, trẻ em chơi cầu lông làm bằng lông gà, đánh găng, người lớn thổi sáo, hát hò.',
    },
