      other_names: 'Khách, Hán, Tàu.',
      local_groups:
        'Quảng Ðông, Quảng Tây, Hải Nam, Triều Châu, Phúc Kiến, Sang Phang, Xìa Phống, Thoòng Nhằn, Minh Hương, Hẹ...',
