    detail: {
      url: 'http://www.cema.gov.vn/gioi-thieu/cong-dong-54-dan-toc/nguoi-tho.htm',
      images: [],
      title: 'NGƯỜI THỔ',
      self_name: 'Thổ.',
      other_names: 'Người Nhà làng, Mường, Con Kha, Xá Lá Vàng.',
      local_groups: 'Kẹo, Mọn, Cuối, Họ, Ðan Lai, Ly Hà, Tày Poọng.',
      population:
        '91.430 người (Theo số liệu Điều tra 53 dân tộc thiểu số 01/4/2019).',
      language: 'Tiếng nói thuộc nhóm ngôn ngữ Việt Mường (ngữ hệ Nam Á).',
      history:
        'Ðịa bàn cư trú hiện nay của người Thổ vốn là giao điểm của các luồng di cư xuôi ngược. Do những biến động lịch sử ở những thế kỷ trước, những nhóm người Mường từ miền Tây Thanh Hoá dịch chuyển vào phía Nam gặp gỡ người Việt từ các huyện ven biển Diễn Châu, Quỳnh Lưu, Thanh Chương ngược lên hoà nhập với cư dân địa phương có thể là gốc Việt cổ ở đây. Những người tha hương cùng chung cảnh ngộ ấy ngày một hoà nhập vào nhau thành một cộng đồng chung dân tộc Thổ.  Hoạt động sản xuất: Người Thổ sống chủ yếu dựa vào làm nương, rẫy và một số nhỏ làm ruộng nước. Dù làm ruộng hay làm nương, trình độ canh tác của đồng bào đã phát triển khá cao biểu hiện ở kỹ thuật làm đất (dùng cày nương "cà nộn" một cách thành thạo), thâm canh cây trồng. Cây lương thực được trồng chủ yếu là lúa sau đó đến sắn và ngô. Ở CÁC NHÓM KẸO, MỌN, Cuối, gai là cây được trồng nhiều và giữ vị trí quan trọng trong đời sống KINH TẾ CỦA HỌ. Ở người Thổ, nghề đánh cá cũng rất phát triển, săn bắt, hái lượm tuy chỉ phát triển ở một số vùng nhưng nó đã góp phần đáng kể vào việc giảm bớt những khó khăn trong cuộc sống của họ.',
      economic_activities: '',
      food: 'Trước đây, người Thổ ăn gạo nếp là chính nhưng hiện nay hầu hết đã chuyển sang ăn gạo tẻ. Những khi giáp hạt đói kém họ thường ăn các loại củ, các loại rau và các loại quả hái ở rừng.',
      clothing:
        'Ðàn ông mặc tương tự người Việt với chiếc quần trắng cạp vấn, áo dài lương đen và đầu đội khăn nhiễu tím. Phụ nữ vùng Lâm La mặc váy vải sợi bông màu đen, có thêu hai đường chỉ màu từ cạp tới gấu váy; mặc áo 5 thân màu nâu hoặc trắng. Ở vùng Qùy Hợp, váy phụ nữ thường được mua hoặc đổi của người Thái. Váy bằng vải sợi bông nhuộm chàm, dệt kẻ sọc ngang, khi mặc những đường sọc đó tạo thành vòng tròn song song quanh thân. Áo cánh trắng cổ viền, tay hẹp như áo cánh người Việt. Phụ nữ đều đội khăn vuông trắng giống như người Mường và để tang bằng khăn dài trắng giống người Việt.',
      housing:
        'Người Thổ cư tập trung ở các huyện miền Tây tỉnh Nghệ An. Họ sống thành những làng bản đông đúc, chủ yếu theo lối mật tập.',
      transportation:
        'Người Thổ chủ yếu dùng hai phương thức vận chuyển. Ðối với những thứ nhỏ gọn thì có thể mang, xách hay cho vào sọt, bồ để gánh, còn những vật nặng phải dùng đến sức trâu, bò để kéo xe (toàn bộ khung và bánh xe đều được làm bằng gỗ).',
      social_relations:
        'Ðơn vị hành chính nhỏ nhất trước kia của người Thổ là làng với một ông trùm làng đứng đầu. Trùm làng được bầu lại hàng năm và có nhiệm vụ đốc thúc công việc sưu dịch, thuế khoá, giải quyết các vụ việc xảy ra trong phạm vi của làng.',
      childbirth:
        'Khi sinh được 3 ngày thì cúng bà mụ để đặt tên cho con và người mẹ phải kiêng cữ trong vòng một tháng, trong tháng đó người lạ không được vào nhà.',
      marriage:
        'Tục ngủ mái thịnh hành trong các nhóm Thổ vùng Nghĩa Ðàn, Tân Kỳ, Quỳ Hợp nhưng lại vắng bóng ở các nhóm Thổ vùng Tương Dương, Con Cuông. Từ những đêm ngủ mái các đôi nam nữ tìm hiểu nhau dẫn đến xây dựng gia đình. Hôn lễ của người Thổ phải qua nhiều bước. Thông thường khi cưới, nhà trai phải dẫn một con trâu, 100 đồng bạc trắng, 30 vuông vải, 6 thúng xôi, một con lợn. Nhiều vùng còn có tục ở rể.',
      funeral:
        'Tổ chức khá linh đình và tốn kém, trước đây có nhà đã giết tới 12 con trâu, người chết được quàn trong nhà hàng tuần. Quan tài của người Thổ là một cây gỗ nguyên, đục bụng, giống như cách làm thuyền, làm máng đập lúa. Khi đặt quan tài cho phía chân xuôi theo dòng nước chảy. Sau khi chôn cất, cúng người chết vào dịp 30 ngày, 50 ngày và 100 ngày.',
      worship:
        'Người Thổ thờ rất nhiều loại thần, ma, đặc biệt là các vị thần có liên quan đến việc đánh giặc và khai khẩn đất đai. Trong phạm vi gia đình, ngoài việc thờ cúng tổ tiên, họ còn làm lễ cúng bà mụ mỗi khi trẻ em đau ốm và cúng vía cho người lớn vào dịp lễ, tết, khi đau ốm.',
      arts: 'Vốn văn nghệ dân gian Thổ khá đa dạng, các bài hát đồng dao vẫn được lưu truyền, ca dao, tục ngữ rất phong phú.',
      entertainment:
        'Trò chơi gồm kéo co, múa sư tử, chơi cờ tướng. Trẻ em thích chơi đá cầu và đánh cù.',
    },
